export function View({
  viewType = "{{viewType}}",
  itemLabel = "{{itemLabel}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430" }}>
      {viewType === "list" && (
        <div>{[1, 2, 3].map((n) => (<div key={n} style={{ padding: "6px 0", borderBottom: "1px solid #24143014" }}>{itemLabel} {n}</div>))}</div>
      )}
      {viewType === "grid" && (
        <div style={{ display: "flex", gap: 8 }}>{[1, 2, 3].map((n) => (<span key={n} style={{ flex: 1, height: 50, borderRadius: 8, background: accent }} />))}</div>
      )}
      {viewType === "table" && (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <tbody>
            <tr><th style={{ textAlign: "left", padding: "5px 4px", borderBottom: "1px solid #24143014" }}>{itemLabel}</th><th style={{ textAlign: "left", padding: "5px 4px", borderBottom: "1px solid #24143014" }}>Amount</th></tr>
            <tr><td style={{ padding: "5px 4px", borderBottom: "1px solid #24143014" }}>1</td><td style={{ padding: "5px 4px", borderBottom: "1px solid #24143014", color: accent }}>&pound;40</td></tr>
          </tbody>
        </table>
      )}
      <p style={{ margin: "10px 0 0", fontSize: 11, color: "#241430aa" }}>Same data, {viewType} view</p>
    </div>
  );
}
